<script setup lang="ts">
import {computed,ref,watch} from 'vue';import {useRoute,useRouter} from 'vue-router';import {Icon} from '@packages/icon';import {strokeIconPaths} from '@/views/AgentWork/strokeIconPaths';import {agentWorkData} from '@/pinia/agentWork';import {usePhase1} from '@/pinia/phase1';import {phaseSkills,dateText} from './catalog';import LegacyTasks from '@/views/AgentWork/views/dailyTasks.view.vue';
const route=useRoute();const router=useRouter();const work=agentWorkData();const s=usePhase1();const selectedId=ref('');const orderFilter=ref('');const search=ref('');const filter=ref('all');const showBackground=ref(false);const weatherFeedback=ref('');const weatherOrder=computed(()=>orders.value.find(o=>o.id===orderFilter.value)||orders.value[0]);
function weatherDemo(advance=false){const o=weatherOrder.value;if(!o)return;if(advance&&o.weatherEffectiveAt){s.advance(Math.max(0,(o.weatherEffectiveAt-s.now)/60000));weatherFeedback.value='已推进到预计生效时间（本地模拟）';}else weatherFeedback.value=s.weatherSample(o.id)||'天气事件已获取，直接生成异常，结果如下。';}
watch(()=>route.query.projectId,id=>{const project=work.projects.find(p=>p.id===id);if(project&&work.currentProjectId!==id)work.switchProject(project);},{immediate:true});
const legacy=computed(()=>route.query.scope==='legacy'||route.query.scope==='personal'||work.workspaceMode==='conversation'&&!route.query.projectId);const config=computed(()=>s.config(work.currentProjectId));const tasks=computed(()=>phaseSkills.filter(t=>config.value.selectedSkills.includes(t.id)));const task=computed(()=>phaseSkills.find(t=>t.id===selectedId.value));
watch([()=>route.query.taskId,()=>work.currentProjectId],()=>{selectedId.value=phaseSkills.find(t=>t.id===route.query.taskId)?.id||'';orderFilter.value=String(route.query.orderId||'');},{immediate:true});
const orders=computed(()=>s.orders.filter(o=>o.projectId===work.currentProjectId));
function enabled(id:string){const c=config.value;return id==='p1-weather'?c.weather.enabled:id==='p1-status'?c.fenceTargets.length>0&&c.statusUpdates.length>0:id==='p1-late'?c.lateDeparture.enabled||c.lateArrival.enabled:id==='p1-parking'?c.parking.enabled:id==='p1-offline'?c.offline.enabled:c.deviation.enabled;}
function taskLogs(id:string){return s.logs.filter(l=>l.projectId===work.currentProjectId&&l.taskId===id);}
function count(id:string){return taskLogs(id).filter(l=>['开始','结果','提醒','恢复','结束','失败'].includes(l.kind)).length;}
const visibleTasks=computed(()=>tasks.value.filter(t=>(!search.value||`${t.name} ${t.description}`.includes(search.value))&&(filter.value==='all'||enabled(t.id)===(filter.value==='running'))));
const results=computed(()=>taskLogs(selectedId.value).filter(l=>['开始','结果','提醒','恢复','结束','失败'].includes(l.kind)&&(!orderFilter.value||l.orderId===orderFilter.value)).slice().reverse().map(l=>{const logs=taskLogs(l.taskId).filter(x=>x.orderId===l.orderId);const pos=logs.findIndex(x=>x.id===l.id);const previous=logs.slice(0,pos).map((x,i)=>({x,i})).filter(({x})=>['开始','结果','提醒','恢复','结束','失败'].includes(x.kind)).at(-1)?.i??-1;return {...l,facts:logs.slice(0,pos+1).filter(x=>x.kind==='基础事件').at(-1)?.text,steps:logs.slice(previous+1,pos+1),order:orders.value.find(o=>o.id===l.orderId)};}));
function configure(){router.push({path:'/index/projects/detail',query:{projectId:work.currentProjectId,tab:'config'}});}
function toggle(id:string){const c=s.config(work.currentProjectId);if(id==='p1-weather')c.weather.enabled=!c.weather.enabled;else if(id==='p1-status')c.statusUpdates=c.statusUpdates.length?[]:['loading','in_transit','arrived','completed'];else if(id==='p1-late'){const on=enabled(id);c.lateDeparture.enabled=!on;c.lateArrival.enabled=!on;}else {const key=id==='p1-parking'?'parking':id==='p1-offline'?'offline':'deviation';c[key].enabled=!c[key].enabled;}s.saveConfig(work.currentProjectId,c,c.version);}
</script>
<template><LegacyTasks v-if="legacy"/><div v-else class="dt-surface dt-page"><header class="dt-page-header"><div class="dt-title"><Icon :svg="strokeIconPaths.alarmClock" :size="16"/><h1>做任务</h1><span class="dt-project-name">{{work.currentProject.name}}</span></div><div class="dt-actions"><button class="dt-button" @click="router.push({path:'/index/daily-tasks',query:{projectId:work.currentProjectId,scope:'legacy'}})">其他任务与邮件</button><button class="dt-icon" aria-label="返回智能体工作台" @click="router.push('/index/agent')"><Icon :svg="strokeIconPaths.msg" :size="16"/></button></div></header><div class="dt-page-body" :class="{'has-panel':task}"><div class="dt-task-column"><div class="dt-list-toolbar"><div class="dt-list-heading"><span>{{tasks.length}}项任务 <span class="dt-secondary">· {{tasks.filter(t=>enabled(t.id)).length}}项已开启</span></span><button class="dt-button primary" @click="configure"><Icon :svg="strokeIconPaths.plus" :size="15"/>配置任务</button></div><div class="dt-type-filter"><button aria-pressed="true">持续监听任务</button></div><div class="dt-filters"><div class="dt-search"><Icon :svg="strokeIconPaths.search" :size="14"/><input v-model="search" aria-label="搜索任务" placeholder="搜索任务"/></div><select v-model="filter" aria-label="任务状态筛选"><option value="all">全部状态</option><option value="running">已开启</option><option value="paused">已暂停</option></select></div></div><section class="dt-task-area" aria-label="项目做任务列表"><div class="dt-task-grid"><article v-for="t in visibleTasks" :key="t.id" class="dt-task-card" :class="{selected:selectedId===t.id}"><button class="dt-task-main" :aria-label="`查看任务 ${t.name}`" :aria-pressed="selectedId===t.id" @click="selectedId=t.id"><div class="dt-task-heading"><span class="dt-task-symbol"><Icon :svg="t.id==='p1-late'?strokeIconPaths.alarmClock:strokeIconPaths.zap" :size="17"/></span><h2>{{t.name}}</h2><span class="dt-badge" :class="{blue:enabled(t.id)}">{{enabled(t.id)?'已开启':'已暂停'}}</span></div><p class="dt-trigger">{{t.id==='p1-weather'?'天气消息触发 · 次日0点预计生效':t.id==='p1-late'?'定时检查 · 计划时间 + 容许延迟':'条件触发 · 收到订阅基础事件'}}</p><p class="dt-task-description" :title="t.description">{{t.description}}</p></button><footer class="dt-task-footer"><div class="dt-task-meta"><span>{{count(t.id)}}条结果</span></div><div class="dt-task-actions"><button class="dt-icon" :aria-label="`编辑 ${t.name}`" title="编辑" @click="configure"><Icon :svg="strokeIconPaths.edit" :size="15"/></button><button class="dt-icon" :aria-label="`查看结果 ${t.name}`" title="查看执行结果" @click="selectedId=t.id"><Icon :svg="strokeIconPaths.list" :size="15"/></button><button class="dt-icon" :aria-label="`${enabled(t.id)?'暂停':'启动'} ${t.name}`" @click="toggle(t.id)"><Icon :svg="enabled(t.id)?strokeIconPaths.pause:strokeIconPaths.play" :size="15"/></button></div></footer></article></div><div v-if="!visibleTasks.length" class="dt-empty">暂无匹配任务，请在项目配置中选择Skill。</div></section></div><aside v-if="task" class="dt-run-panel" aria-label="任务运行面板"><header class="dt-run-header"><div class="dt-title"><Icon :svg="strokeIconPaths.bot" :size="16"/><h2>{{task.name}}</h2></div><div class="dt-actions"><button class="dt-background-toggle" :aria-expanded="showBackground" @click="showBackground=!showBackground">任务背景</button><button class="dt-icon" aria-label="关闭运行面板" @click="selectedId='' "><Icon :svg="strokeIconPaths.x" :size="16"/></button></div></header><div class="dt-run-body"><div class="dt-run-scroll" :key="task.id"><div class="dt-run-section-heading"><h3>执行结果 <span class="dt-secondary">{{results.length}}</span></h3><select v-model="orderFilter" aria-label="任务运单范围"><option value="">全部运单</option><option v-for="o in orders" :key="o.id" :value="o.id">{{o.id}}</option></select></div><div v-if="task.id==='p1-weather'" class="dt-run-context"><p>不发送车机提醒；有效天气事件直接生成异常，无研判参数。</p><p v-for="o in orders.filter(o=>!orderFilter||o.id===orderFilter)" :key="o.id">{{o.id}} · {{s.weatherState(o)}} · 预计{{dateText(o.weatherEffectiveAt)}} · 截止{{dateText(o.expiresAt)}}</p><button class="dt-button" @click="router.push({path:'/index/detail',query:{orderId:orderFilter||orders[0]?.id}})">进入运单详情</button><button class="dt-button" :disabled="!weatherOrder?.weatherEffectiveAt" @click="weatherDemo(true)">模拟推进至预计天气生效时间</button><button class="dt-button" @click="weatherDemo()">模拟暴雨预警消息</button><p role="status">{{weatherFeedback}}</p></div><p class="dt-secondary">V1.1 · 本地模拟；原始事件与纠正结果均保留。</p><section v-for="run in results" :key="run.id" class="dt-run"><header><div><strong>{{run.orderId}} · {{run.order?.plate}}</strong><small>{{dateText(run.at)}} · {{run.kind}}</small></div><span class="dt-badge" :class="{warning:run.kind==='失败'}">{{run.kind}}</span></header><p class="dt-run-result">{{run.text}}</p><p v-if="run.facts&&run.kind==='结果'" class="dt-run-context">{{run.facts}}</p><button class="dt-text-button" @click="router.push({path:'/index/detail',query:{orderId:run.orderId}})">运单详情</button><details class="dt-run-steps"><summary>执行详情</summary><ol><li v-for="step in run.steps" :key="step.id"><Icon :svg="strokeIconPaths.check" :size="13"/><div><strong>{{step.kind}} · {{dateText(step.at)}}</strong><p>{{step.text}}</p></div></li></ol></details></section><div v-if="!results.length" class="dt-empty compact">暂无执行结果；创建及订阅信息在后续结果的执行详情中展示。</div></div><aside class="dt-background-rail" :class="{'is-open':showBackground}"><section class="dt-task-summary"><div class="dt-summary-title"><h2>{{task.name}}</h2><span class="dt-badge blue">{{enabled(task.id)?'已开启':'已暂停'}}</span></div><dl class="dt-summary-metrics"><div><dt>结果数量</dt><dd>{{count(task.id)}}条</dd></div><div><dt>配置版本</dt><dd>v{{config.version}}</dd></div></dl><p>{{task.description}}</p><p>创建后读取最新配置，最多监听72小时；结束信息保留为执行结果。</p></section></aside></div></aside></div></div></template>
<style src="../AgentWork/dailyTasks.css"></style>
